<?php $s=$result['summary']; ?><style>.dr{max-width:1180px}.dr-head{display:flex;justify-content:space-between;gap:16px;align-items:center;flex-wrap:wrap}.dr-metrics{display:grid;grid-template-columns:repeat(auto-fit,minmax(145px,1fr));gap:10px;margin:20px 0}.dr-metric{background:#fff;border-radius:16px;padding:15px}.dr-metric strong{display:block;font-size:23px;color:#17312d}.dr-metric span{font-size:12px;color:#70857e}.dr-table{background:#fff;border-radius:23px;padding:8px 20px;overflow:auto}.dr-table table{width:100%;border-collapse:collapse;min-width:950px}.dr-table th,.dr-table td{text-align:left;padding:15px 9px;border-bottom:1px solid #e8efed;vertical-align:top}.dr-table th{font-size:11px;color:#758a84;text-transform:uppercase}.dr-pill{display:inline-block;padding:5px 9px;border-radius:999px;background:#e3f4ef;color:#0d8076;font-size:12px;font-weight:800}</style><div class="dr"><div class="dr-head"><div><h2 style="margin:0 0 6px">Directors Import Report</h2><p style="margin:0;color:#637a73"><?= htmlspecialchars($result['filename']) ?> · Sensitive identifiers are excluded</p></div><div style="display:flex;gap:10px"><a data-no-ajax href="/staff/directors/import/report/<?= (int)$result['import_id'] ?>/download" style="padding:12px 16px;border-radius:12px;background:#edf5f2;color:#0d8076;font-weight:800">Download report CSV</a><a href="/staff/clients" style="padding:12px 16px;border-radius:12px;background:#0d9488;color:#fff;font-weight:800">View clients</a></div></div><div class="dr-metrics"><?php foreach(['total'=>'Total rows','directors_created'=>'Created','directors_updated'=>'Updated','placeholders_upgraded'=>'Placeholders upgraded','directors_reused'=>'Reused','links_created'=>'Links created','links_reused'=>'Links reused','rows_flagged'=>'Flagged','failed'=>'Failed','companies_not_found'=>'Not found','ambiguous_companies'=>'Ambiguous','needing_details'=>'Need details'] as $key=>$label): ?><div class="dr-metric"><strong><?= (int)$s[$key] ?></strong><span><?= $label ?></span></div><?php endforeach; ?></div><div class="dr-table"><table><thead><tr><?php foreach(['CSV row','Director','Linked companies','Director result','Link result','Profile','Warnings / errors'] as $h): ?><th><?= $h ?></th><?php endforeach; ?></tr></thead><tbody><?php foreach($result['rows'] as $r): ?><tr><td><?= (int)$r['line'] ?></td><td><strong><?= htmlspecialchars($r['data']['name']) ?></strong></td><td><?= htmlspecialchars($r['data']['companies']) ?></td><td><span class="dr-pill"><?= htmlspecialchars($r['director_result']??$r['result']) ?></span></td><td><?= htmlspecialchars($r['link_result']??'') ?></td><td><?= htmlspecialchars($r['profile_status']??'') ?></td><td style="color:#a45f23"><?= htmlspecialchars(implode('; ',array_merge($r['warnings']??[],$r['errors']??[]))) ?></td></tr><?php endforeach; ?></tbody></table></div></div>
